const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const convexSiteUrl = $env.CONVEX_SITE_URL;

if (!secret || !convexSiteUrl) {
  throw new Error('Missing LENDLOOP_WEBHOOK_SECRET or CONVEX_SITE_URL in n8n environment.');
}

const pathname = '/api/n8n/overdue-loans';
const ts = String(Math.floor(Date.now() / 1000));
const sig = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(`${ts}.${pathname}`)
  .digest('hex');

return [{
  json: {
    url: `${convexSiteUrl}${pathname}`,
    ts,
    sig
  }
}];

const crypto = require('crypto');
const response = $input.first().json;
const overdueLoans = response.overdueLoans || [];
const asOfDate = response.asOfDate || new Date().toISOString().slice(0, 10);

if (overdueLoans.length === 0) {
  return [];
}

return overdueLoans.map((loan) => {
  const reminderMessage = `Hi ${loan.borrowerName}, friendly reminder that ${loan.toolName} (borrowed from ${loan.lenderName}) was due on ${loan.endDate} (${loan.daysOverdue} day(s) overdue). Please coordinate return on LendLoop.`;

  // Log reminder delivery using strictly minimized fields
  console.log(JSON.stringify({
    channel: 'lendloop_overdue_reminder',
    to: loan.borrowerEmail,
    loanId: loan.loanId,
    toolName: loan.toolName,
    daysOverdue: loan.daysOverdue,
    idempotencyKey: loan.idempotencyKey,
    message: reminderMessage,
    sentAt: new Date().toISOString()
  }));

  const callbackPayload = {
    idempotencyKey: loan.idempotencyKey,
    loanId: loan.loanId,
    reminderDateKey: asOfDate,
    status: 'delivered',
    summary: `Overdue reminder sent (${loan.daysOverdue}d overdue)`,
    attemptCount: 1
  };

  const rawCallbackBody = JSON.stringify(callbackPayload);
  const ts = String(Math.floor(Date.now() / 1000));
  const sig = 'sha256=' + crypto
    .createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET)
    .update(`${ts}.${rawCallbackBody}`)
    .digest('hex');

  return {
    json: {
      callbackUrl: `${$env.CONVEX_SITE_URL}/api/n8n/reminder-callback`,
      rawCallbackBody,
      ts,
      sig,
      idempotencyKey: loan.idempotencyKey
    }
  };
});
